PAT=re.compile(r'(?<!\d)(\d{5})\s*(?:\.\s*){0,5}([act])?\s*(?:\.\s*){0,5}(\d{3,9})(?!\d)')

def extract(pdf):
    doc=fitz.open(stream=pdf,filetype='pdf');rows=[]
    for pno,p in enumerate(doc,1):
        txt=p.get_text('text',sort=False)
        for m in PAT.finditer(txt):
            n,mark,amount=m.groups();v=int(amount)
            if not 0<v<=5000000:continue
            rows.append({'numero':n,'marca':mark or '', 'euros_billete':v,'pagina':pno,'evidencia':txt[max(0,m.start()-22):m.end()+22].replace('\n',' ')})
    return rows

def get_majors(data):
    out={};invalid=[]
    for key in ('primerPremio','segundoPremio','tercerosPremios','cuartosPremios','quintosPremios'):
        value=data.get(key,[])
        for v in (value if isinstance(value,list) else [value]):
            if not isinstance(v,dict) or 'decimo' not in v or 'prize' not in v:continue
            n=str(v['decimo']).zfill(5);cents=int(v['prize'])
            if cents%100:invalid.append({'numero':n,'centimos':cents})
            out[n]={'categoria':key,'euros_decimo':cents/100}
    return out,invalid

def main():
    assets=pickle.loads(zlib.decompress(base64.b85decode(PAYLOAD)))
    out=pathlib.Path('salida_107');out.mkdir(exist_ok=True)
    report={'version':VERSION,'publicable':False,'motor_validado':False,'catalogo_validado':False,
      'historico_modificado':False,'fuente':'Copias historicas SELAE conservadas; no consulta en directo',
      'fecha_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'anios':{},
      'alcance':'Contraste de componentes contra entradas literales de PDF; acumulaciones pendientes de validacion oficial independiente'}
    for year in (2024,2025):
        pdf=assets[f'pdf_{year}.pdf'];cat=json.loads(assets[f'catalogo_{year}.json']);official=json.loads(assets[f'json_{year}.json'])
        rows=extract(pdf);majors,invalid=get_majors(official)
        candidates={r['numero'] for r in cat['candidatos']}
        by_number=collections.defaultdict(list)
        for r in rows:by_number[r['numero']].append(r)
        first=str(official['primerPremio']['decimo']).zfill(5)
        reintegro_digit=first[-1]
        no_mark={r['numero'] for r in rows if not r['marca'] and r['euros_billete']==1000}
        diffs=[];marked_mismatches=[];main_matches=[];main_mismatches=[];components=[]
        by_cat=collections.Counter(); multi=0;total=0;marked_total=0;unknown=[]
        for n_int in range(100000):
            n=f'{n_int:05d}';parts=[]
            if n in majors:
                major=majors[n];parts.append({'origen':'json_oficial','categoria':major['categoria'],'euros_decimo':major['euros_decimo']})
                pdf_major=[r for r in by_number[n] if not r['marca'] and r['euros_billete']==round(major['euros_decimo']*10)]
                (main_matches if pdf_major else main_mismatches).append(n)
            if n in candidates:
                parts.append({'origen':'catalogo_pdf_103','categoria':'pedrea_candidata','euros_decimo':100})
            # Las entradas a/c/t del PDF son componentes separados, NO importes totales del numero.
            # No se interpreta una entrada sin marca como premio mayor adicional.
            for r in by_number[n]:
                if r['marca'] in ('a','c','t'):
                    parts.append({'origen':'pdf_nativo','categoria':{'a':'aproximacion','c':'centena','t':'terminacion'}[r['marca']],
                      'euros_decimo':r['euros_billete']/10,'pagina':r['pagina']})
                    if r['euros_billete']%10:marked_mismatches.append({'numero':n,'importe':r['euros_billete']})
            if n[-1]==reintegro_digit and n!=first:
                parts.append({'origen':'regla_reintegro_pendiente_contraste','categoria':'reintegro','euros_decimo':20})
            for p in parts:by_cat[p['categoria']]+=1
            amount=sum(p['euros_decimo'] for p in parts)
            total+=amount;multi+=len(parts)>1
            if parts:
                components.append({'numero':n,'total_experimental_euros_decimo':amount,'componentes':parts,
                  'requiere_validacion_acumulacion':len(parts)>1 or n in majors})
        # Comprobaciones: una entrada sin marca de 1000 debe coincidir con el catalogo nativo.
        diff_catalog=sorted(candidates-no_mark);diff_pdf=sorted(no_mark-candidates)
        # Ejemplos de controversias: premio principal puede coincidir con terminacion y reintegro;
        # no se descuenta ninguna categoria sin evidencia normativa.
        samples={n:next((r for r in components if r['numero']==n),{'numero':n,'total_experimental_euros_decimo':0,'componentes':[]})
          for n in [first,'11840','00080','02880',str((int(first)-1)%100000).zfill(5),str((int(first)+1)%100000).zfill(5)]}
        detail={'anio':year,'id_sorteo':official.get('drawIdSorteo'),'sha256_pdf':hashlib.sha256(pdf).hexdigest(),
          'sha256_coincide_catalogo_103':hashlib.sha256(pdf).hexdigest()==cat['resumen']['sha256_pdf'],
          'filas_pdf_nativo':len(rows),'pedrea_candidatos':len(candidates),
          'pedrea_sin_marca_pdf_nativo':len(no_mark),'diferencias_catalogo_vs_pdf_nativo':{'solo_catalogo':diff_catalog,'solo_pdf':diff_pdf},
          'premios_principales_json':len(majors),'premios_principales_coincidentes_pdf':len(main_matches),
          'premios_principales_no_localizados_en_pdf':main_mismatches,'premios_json_centimos_no_enteros':invalid,
          'filas_marcadas_no_divisibles_por_10':marked_mismatches,'componentes_por_categoria':dict(by_cat),
          'numeros_con_multiples_componentes':multi,'suma_experimental_por_decimo_de_todos_los_numeros_euros':total,
          'ejemplos':samples,'advertencias':[
            'Las marcas a/c/t son entradas individuales del PDF, no necesariamente total pagadero.',
            'El reintegro se calcula por terminacion y excepcion del Gordo, pero la acumulabilidad con otras categorias requiere contraste oficial.',
            'El premio principal del JSON puede ya reflejar un total: se compara contra PDF, no se supone independiente de todo premio derivado.',
            'La suma de todos los numeros no equivale al presupuesto oficial de premios por serie sin validar reglas y multiplicidades.',
            'No es una certificacion economica ni autorizacion para publicar premios.']}
        (out/f'auditoria_economica_navidad_{year}_107.json').write_text(json.dumps(detail,ensure_ascii=False,indent=2),encoding='utf-8')
        (out/f'componentes_navidad_{year}_107.json').write_text(json.dumps(components,ensure_ascii=False,separators=(',',':')),encoding='utf-8')
        report['anios'][str(year)]={'pedrea_catalogo':len(candidates),'pedrea_pdf_nativo':len(no_mark),
          'diferencias_catalogo_pdf':len(diff_catalog)+len(diff_pdf),'premios_principales_json':len(majors),
          'premios_principales_contraste_pdf':len(main_matches),'premios_principales_no_localizados':len(main_mismatches),
          'componentes_por_categoria':dict(by_cat),'numeros_multicomponente':multi,
          'sha256_coincide':detail['sha256_coincide_catalogo_103']}
        print(year,report['anios'][str(year)])
    (out/'informe_navidad_107.json').write_text(json.dumps(report,ensure_ascii=False,indent=2),encoding='utf-8')
    if any(x['diferencias_catalogo_pdf'] or not x['sha256_coincide'] for x in report['anios'].values()):
        raise SystemExit('Hay discrepancias entre catalogo y PDF: revisar informe antes de continuar')
if __name__=='__main__':main()
